{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free Q-values to determine the net stage 1 values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 action chosen in the previous trial, regardless of its outcome.",
      "params": [
        {
          "name": "pers",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers_term = np.zeros(2)\nif last_action_1 != -1:\n    pers_term[last_action_1] = pers\n    \nq1_vals = beta * q_stage1_net + pers_term\n...\nlast_action_1 = action_1[trial]",
      "expressible_in_slots": true
    }
  ]
}
